function teamSection(){return `<section class="section team" id="team" aria-labelledby="team-title"><div class="sectiontop"><div><div class="eyebrow">${tr('The people behind the community','الناس وراء اللمة')}</div><h2 id="team-title">${tr('Meet the executive team.','تعرّف على الفريق التنفيذي.')}</h2><p>${tr('The committee listed on SSO’s public club directory.','الفريق المدرج في دليل المنظمة العام.')}</p></div><a class="textlink" href="https://campus.hellorubric.com/?s=14548" target="_blank" rel="noopener noreferrer">${tr('View club directory','عرض دليل المنظمة')} </a></div>${demoContent.profiles.some(Boolean)?`<p class="demo-notice">${tr('Local demo profile edits are being shown in this browser.','تعرض هذه الصفحة تعديلات ملفات تجريبية محلية في متصفحك.')}</p>`:''}<div class="team-grid">${executives.map(e=>`<article class="team-card"><div class="team-portrait" aria-hidden="true"><span dir="ltr">${e.initials}</span></div><div class="team-caption"><p class="team-role">${t(e.role)}</p><h3 dir="ltr">${e.name}</h3></div></article>`).join('')}</div><p class="team-note">${tr('Names and roles checked 9 October 2026. Portraits will be added from the club’s executive introductions once available.','تم التحقق من الأسماء والمناصب في ٩ أكتوبر ٢٠٢٦. ستُضاف الصور من منشورات التعريف بالفريق عند توفرها.')}</p></section>`}

function persist(){try{localStorage.setItem('sso-lang',lang)}catch{}}
function render(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';$('#app').innerHTML=`<header><nav class="nav" aria-label="${tr('Main navigation','التنقل الرئيسي')}"><a class="brand" href="#main"><img src="club-logo.jpg" alt="SSO UofA logo"><div><b>SSO <span style="font-weight:400">UofA</span></b><small>${tr('SUDANESE STUDENTS ORGANIZATION','منظمة الطلاب السودانيين')}</small></div></a><button class="menu" id="menu" aria-expanded="false" aria-controls="navlinks" aria-label="${tr('Open menu','فتح القائمة')}">☰</button><div class="navlinks" id="navlinks"><a href="#about">${tr('Home','الرئيسية')}</a><a href="#guide">${tr('New here?','جديد هنا؟')}</a><a href="#events">${tr('Events','الفعاليات')}</a><a href="#gallery">${tr('Gallery','الصور')}</a><a href="#merch">${tr('Merch','المنتجات')}</a><a href="#team">${tr('Our team','فريقنا')}</a><a href="#resources">${tr('Student resources','موارد الطلاب')}</a><a href="#volunteer">${tr('Volunteer','تطوّع')}</a><a href="#contact">${tr('Contact','تواصل')}</a><button class="lang" id="lang" aria-label="${tr('Switch to Arabic','Switch to English')}">${tr('العربية','English')}</button><a class="button" href="#join">${tr('Get involved','شارك معنا')} </a></div></nav></header><main id="main"><section class="hero fade"><div><div class="eyebrow">${tr('University of Alberta · Edmonton','جامعة ألبرتا · إدمونتون')}</div><h1>${tr('A little Sudan.<br>A lot of <em>home.</em>','شوية سودان.<br>كتير من <em>دفء البيت.</em>')}</h1><p>${tr('Culture that connects us. Friendships that stay with us. A home on campus for Sudanese students—and everyone curious to share in it.','ثقافة تجمعنا. وصداقات تبقى معنا. مساحة في الجامعة للطلاب السودانيين ولكل من يرغب في مشاركتنا.')}</p><div class="heroactions"><a class="button" href="#join">${tr('Find your people','تعال واتعرف علينا')} </a><a class="button light" href="#events">${tr('Explore our community','استكشف مجتمعنا')} </a></div><div class="herofoot"><div class="flag" aria-hidden="true"><i></i><i></i><i></i></div><span>${tr('Sudanese roots. Edmonton connections.','جذور سودانية. وروابط في إدمونتون.')}</span></div></div><div class="art"><img src="heritage.svg" alt="${tr('Original illustration of Sudanese pyramids, warm sandstone buildings, a textile and a cup of tea','رسم أصلي لأهرامات سودانية ومبانٍ بألوان دافئة ونسيج وكوب شاي')}"><span class="arabic-note" lang="ar" dir="rtl">أهلاً بيك</span><div class="art-caption">${tr('A LITTLE PIECE OF HOME, WHEREVER WE GO.','حتة من البيت، وين ما مشينا.')}</div></div></section><div class="ticker" aria-hidden="true"><span>${tr('CULTURE','ثقافة')}</span><i>✳</i><span>${tr('CONNECTION','تواصل')}</span><i>✳</i><span>${tr('COMMUNITY','مجتمع')}</span><i>✳</i><span lang="ar">لمة سودانية</span><i>✳</i><span>SSO UofA</span></div><section class="about" id="about"><div><div class="eyebrow">${tr('The space between here & home','المسافة بين هنا والبيت')}</div><h2>${tr('Different journeys.<br>A shared table.','رحلات مختلفة.<br>ولمة بتجمعنا.')}</h2><a class="textlink" href="${social}" target="_blank" rel="noopener noreferrer">${tr('Meet SSO on Instagram','تعرّف على المنظمة عبر إنستغرام')} </a></div><div><p class="lead">${tr('SSO brings Sudanese culture, friendships and community to the University of Alberta. A little piece of home, wherever your journey began.','تجمع المنظمة الثقافة السودانية والصداقات والمجتمع في جامعة ألبرتا. حتة من البيت، مهما كانت بداية رحلتك.')}</p><div class="values"><div class="value"><strong>01 · ${tr('Celebrate culture','احتفاء بالثقافة')}</strong><p>${tr('A place for our stories, music, creativity and the everyday things that feel like home.','مساحة لقصصنا وموسيقانا وإبداعنا وتفاصيلنا اليومية التي تشبه البيت.')}</p></div><div class="value"><strong>02 · ${tr('Make connections','روابط وصداقات')}</strong><p>${tr('Find familiar faces, meet new ones and make campus feel a little smaller.','وجوه مألوفة وصداقات جديدة تجعل الجامعة أكثر قرباً.')}</p></div><div class="value"><strong>03 · ${tr('Show up together','مع بعض')}</strong><p>${tr('Explore student-led gatherings and conversations through SSO’s own channels.','تابع اللقاءات والنقاشات الطلابية عبر قنوات المنظمة نفسها.')}</p></div></div></div></section><section class="section" id="events"><div class="sectiontop"><div><div class="eyebrow">${tr('Around the community','في مجتمعنا')}</div><h2>${tr('Good things happen<br>when we gather.','الحاجات الحلوة<br>بتبدأ باللمة.')}</h2><p>${tr('Find what’s coming up, then revisit moments from our community.','تعرّف على الفعاليات القادمة، واسترجع لحظات من مجتمعنا.')}</p></div><a class="textlink" href="${social}" target="_blank" rel="noopener noreferrer">${tr('Latest announcements','أحدث الإعلانات')} </a></div><a class="textlink" href="#calendar" style="display:inline-block;margin-bottom:20px">${tr('View event calendar','عرض تقويم الفعاليات')} </a><div class="event-upcoming"><div class="eyebrow">${tr('Next on the calendar','القادم في التقويم')}</div><h2 class="event-group-title">${tr('Upcoming events','الفعاليات القادمة')}</h2><div class="events" id="upcoming-list"></div></div><div class="event-archive"><div class="eyebrow">${tr('Community memories','ذكريات المجتمع')}</div><h2 class="event-group-title">${tr('Past events & highlights','الفعاليات السابقة واللقطات')}</h2><p class="archive-intro">${tr('An archive of public posts and highlights. These events are not open for registration.','أرشيف للمنشورات واللقطات العامة. هذه الفعاليات ليست مفتوحة للتسجيل.')}</p><div class="filters" role="group" aria-label="${tr('Filter past events','تصفية الفعاليات السابقة')}">${[['all',P('All moments','كل اللحظات')],['culture',P('Culture & stories','ثقافة وقصص')],['community',P('Community','مجتمع')]].map(([v,label])=>`<button class="filter ${filter===v?'active':''}" data-filter="${v}" aria-pressed="${filter===v}">${t(label)}</button>`).join('')}</div><div class="events" id="event-list"></div><p style="font-size:10px;color:var(--muted);margin-top:20px">${tr('Posters are original website illustrations, not official event artwork.','الملصقات رسومات أصلية للموقع وليست ملصقات رسمية للفعاليات.')}</p></div></section>${calendarSection()}${merchSection()}${checkoutSection()}${productSection()}${teamSection()}<section class="join" id="join"><div><div class="eyebrow">${tr('There’s room for you here','في مكان ليك هنا')}</div><h2>${tr('Come for the culture.<br>Stay for the people.','تعال عشان الثقافة.<br>خليك عشان الناس.')}</h2><a class="button light" href="#volunteer">${tr('Join the volunteer pool','انضم لقائمة المتطوعين')} </a><p>${tr('Want to join, volunteer or bring an idea to life? Start a conversation with SSO. The club can share its current membership and event registration details.','عايز تنضم أو تتطوع أو تحقق فكرة؟ ابدأ بتواصل مع المنظمة. هي المصدر لتفاصيل العضوية والتسجيل في الفعاليات الحالية.')}</p><div class="join-demo-actions"><button class="button" id="try-onboarding">${tr('Join the community','انضم للمجتمع')} </button><a class="textlink" href="${social}" target="_blank" rel="noopener noreferrer">${tr('Contact SSO on Instagram','تواصل مع المنظمة عبر إنستغرام')} </a></div><p class="join-demo-note">${tr('Free membership. Everyone welcome. Explore joining through the club’s Rubric page.','عضوية مجانية والجميع مرحّب بهم. استكشف الانضمام عبر صفحة المنظمة على روبرك.')}</p></div><div class="joinways">${[[P('Join the community','انضم للمجتمع'),P('Ask the club how to become a member and hear about its next gathering.','اسأل المنظمة عن طريقة العضوية ولقائها القادم.')],[P('Lend a hand','شارك بجهدك'),P('Join the volunteer pool and choose shifts shared in the group.','انضم لقائمة المتطوعين واختر المهام المنشورة في المجموعة.')],[P('Bring an idea','تعال بفكرة'),P('Pitch a collaboration, cultural activity or student-led conversation.','اقترح تعاوناً أو نشاطاً ثقافياً أو نقاشاً طلابياً.')]].map(([title,desc],i)=>`<div class="joinway"><span class="num">0${i+1}</span><div><b>${t(title)}</b><small>${t(desc)}</small></div></div>`).join('')}</div></section>${prayerSection()}<section class="section resources" id="resources"><div><div class="eyebrow">${tr('Campus, made easier','الجامعة أسهل')}</div><h2>${tr('Your everyday<br>campus tools.','أدواتك اليومية<br>في الجامعة.')}</h2><p style="font-size:13px;line-height:1.8;color:var(--muted)">${tr('Quick access for your term: courses, registration and deadlines. Official university pages, reviewed 9 October 2026.','وصول سريع خلال الفصل: المقررات والتسجيل والمواعيد. صفحات رسمية للجامعة رُوجعت في ٩ أكتوبر ٢٠٢٦.')}</p></div><div><label class="eyebrow" for="resource-search">${tr('Find a resource','ابحث عن مورد')}</label><input class="resource-search" id="resource-search" type="search" placeholder="${tr('Try courses, registration, deadlines…','جرّب مقررات، تسجيل، مواعيد…')}"><div id="resource-list"></div></div></section>${extraSections()}${newsletterSection()}<section class="faq" id="faq"><div><div class="eyebrow">${tr('FAQ','الأسئلة الشائعة')}</div><h2>${tr('Before you<br>say hello.','قبل ما<br>تقول مرحب.')}</h2></div><div>${faqs.map(f=>`<details><summary>${t(f.q)}</summary><p>${t(f.a)}</p></details>`).join('')}</div></section></main><footer><div class="footerinner"><div><a class="brand" href="#main"><img src="club-logo.jpg" alt="SSO UofA logo"><div><b>SSO UofA</b><small>${tr('SUDANESE STUDENTS ORGANIZATION','منظمة الطلاب السودانيين')}</small></div></a><p>${tr('Sudanese roots. Edmonton connections. Culture, friendship and a shared home at the University of Alberta.','جذور سودانية وروابط في إدمونتون. ثقافة وصداقات وبيت يجمعنا في جامعة ألبرتا.')}</p></div><div class="footer-contact"><div class="footerlinks"><a href="${social}" target="_blank" rel="noopener noreferrer">Instagram </a><a href="#contact">${tr('Contact','تواصل')}</a><a href="#guide">${tr('New here?','جديد هنا؟')}</a><a href="#gallery">${tr('Gallery','الصور')}</a></div><p class="land-ack">${tr('We acknowledge that Edmonton is on Treaty 6 territory and the Métis homeland.','نقر بأن إدمونتون تقع على أراضي المعاهدة السادسة وموطن شعب الميتي.')}</p></div></div><div class="footerbottom"><span>© 2026 · ${tr('SSO UofA','منظمة الطلاب السودانيين')}</span><span>${tr('From Sudan, with love.','من السودان، بكل حب.')} ♡</span></div></footer>`;
$('#lang').onclick=()=>{lang=lang==='en'?'ar':'en';persist();render()};$('#menu').onclick=()=>{const open=$('#navlinks').classList.toggle('open');$('#menu').setAttribute('aria-expanded',open);$('#menu').setAttribute('aria-label',open?tr('Close menu','إغلاق القائمة'):tr('Open menu','فتح القائمة'))};document.querySelectorAll('#navlinks a').forEach(a=>a.addEventListener('click',()=>{$('#navlinks').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');$('#menu').setAttribute('aria-label',tr('Open menu','فتح القائمة'))}));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x.dataset.filter===filter);x.setAttribute('aria-pressed',x.dataset.filter===filter)});drawEvents()});$('#resource-search').value=resourceQuery;$('#resource-search').oninput=e=>{resourceQuery=e.target.value;drawResources()};applySitePage();drawEvents();drawResources();if(currentSitePage==='resources')bindPrayer();bindOnboarding();bindCalendar();bindMerch();bindCheckout();bindProduct();bindNewsletter();bindCommunity();bindVolunteer()}
function drawEvents(){const today=campusToday();const upcoming=events.filter(e=>e.calendarDate&&e.calendarDate>=today);const list=events.filter(e=>(!e.calendarDate||e.calendarDate<today)&&(filter==='all'||filter===e.category));const cards=(items)=>items.map(e=>`<article class="event"><div class="poster ${e.style}" aria-hidden="true"><span>SSO UofA</span><b>${e.poster}</b><span class="tiny">${e.calendarDate&&e.calendarDate>=today?tr('UPCOMING EVENT','فعالية قادمة'):tr('COMMUNITY ARCHIVE','أرشيف المجتمع')}</span></div><div class="eventmeta"><span class="tag">${e.demo?tr('DEMO · ','تجريبي · '):''}${e.category==='culture'?tr('Culture & stories','ثقافة وقصص'):tr('Community','مجتمع')}</span><time>${e.calendarDate?formatEventDate(e.calendarDate)+' · '+(e.calendarDate<today?tr('Past','سابق'):tr('Upcoming','قادم')):t(e.date)}</time></div><h3>${t(e.title)}</h3><p>${t(e.desc)}</p><div class="eventactions"><button class="details" data-details="${e.id}">${e.calendarDate&&e.calendarDate>=today?tr('Event details','تفاصيل الفعالية'):tr('Explore the moment','استكشف اللحظة')} </button></div></article>`).join('');$('#upcoming-list').innerHTML=upcoming.length?cards(upcoming):`<div class="upcoming-empty"><span class="tag">${tr('Awaiting confirmed dates','بانتظار مواعيد مؤكدة')}</span><h3>${tr('More moments to look forward to.','لحظات جديدة في انتظارنا.')}</h3><p>${tr('No upcoming dates are confirmed on this website yet. Follow SSO for the latest announcements.','لا توجد مواعيد قادمة مؤكدة على هذا الموقع بعد. تابع المنظمة للاطلاع على أحدث الإعلانات.')}</p><a class="textlink" href="${social}" target="_blank" rel="noopener noreferrer">${tr('Follow announcements on Instagram','تابع الإعلانات على إنستغرام')} </a></div>`;$('#event-list').innerHTML=list.length?cards(list):`<div class="empty">${tr('No matching activities. Try another category.','لا توجد أنشطة مطابقة. جرّب فئة أخرى.')}</div>`;document.querySelectorAll('[data-details]').forEach(b=>b.onclick=()=>openEvent(b.dataset.details))}

function openEvent(id){const e=events.find(x=>x.id===id);const d=$('#event-dialog');d.innerHTML=`<button class="close" id="close-dialog" aria-label="${tr('Close details','إغلاق التفاصيل')}">×</button><span class="tag">${e.calendarDate?formatEventDate(e.calendarDate)+' · '+(e.calendarDate<campusToday()?tr('Past','سابق'):tr('Upcoming','قادم')):t(e.date)}</span><h2 id="event-title">${t(e.title)}</h2><p>${t(e.detail)}</p>${eventExtraDetails(e)}<p class="dialognote">${e.demo?tr('Local sample only. Not a club event.','عينة محلية فقط وليست فعالية للمنظمة.'):e.calendarDate&&e.calendarDate>=campusToday()?tr('Check the original announcement for registration and any updates.','راجع الإعلان الأصلي للتسجيل وأي تحديثات.'):tr('Archive only · No active RSVP or ticket booking through this website.','أرشيف فقط · لا يوجد تأكيد حضور أو حجز تذاكر عبر هذا الموقع.')}</p>${e.demo?'':`<a class="button" href="${e.source}" target="_blank" rel="noopener noreferrer">${tr('View original on Instagram','عرض الأصل على إنستغرام')} </a>`}`;d.showModal();if(e.demo)$('#demo-rsvp').onclick=()=>{$('#demo-rsvp-result').textContent=tr('Demo RSVP complete. No booking or message was created.','اكتملت تجربة التسجيل. لم يتم إنشاء حجز أو إرسال رسالة.')};$('#close-dialog').onclick=()=>d.close();d.onclick=ev=>{if(ev.target===d){const r=d.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)d.close()}}}
function drawResources(){const q=resourceQuery.trim().toLowerCase();const list=resources.filter(r=>(r.title.en+' '+r.title.ar+' '+r.desc.en+' '+r.desc.ar).toLowerCase().includes(q));$('#resource-list').innerHTML=list.length?list.map(r=>`<a class="resource" href="${r.url}" target="_blank" rel="noopener noreferrer"><span><strong>${t(r.title)}</strong><small>${t(r.desc)}</small></span></a>`).join(''):`<div class="empty">${tr('No matching resources. Try a different word.','لا توجد موارد مطابقة. جرّب كلمة أخرى.')}</div>`}
applyDemoContent();render();

let lastEventDay=campusToday();function refreshEventDay(){const day=campusToday();if(day!==lastEventDay){lastEventDay=day;drawEvents();if(typeof drawCalendar==='function')drawCalendar()}}setInterval(refreshEventDay,60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshEventDay()});
